contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt to withdraw an amount 'want' from c by calling withdraw(want) as the owner (this contract is owner).
    // We require the test contract to have enough balance to later receive funds if the call succeeds.
    function run(uint want) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0); // no precondition on want

        // Read before-values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Perform the owner withdraw call. We capture whether it reverted.
        bool reverted;
        c.withdraw(want); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: if want is greater than the prior contract balance then withdraw(want) must revert,
        // and in that case depositsCount and balance remain unchanged. If want <= beforeBal then nothing is asserted here.
        assert(!(want > beforeBal) || (reverted && afterCount == beforeCount && afterBal == beforeBal));
    }

    // allow receiving ETH when withdraw succeeds
    receive() external payable {}
}

